import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import java.nio.charset.Charset;

public class run_test {
    public static void main(String[] args) throws Exception {
        System.out.println("Running testCollisionsWithBytesNew187b...");
        ByteQuadsCanonicalizer symbols =
                ByteQuadsCanonicalizer.createRoot(1).makeChild(JsonFactory.Feature.collectDefaults());

        final int COUNT = 10000;
        for (int i = 0; i < COUNT; ++i) {
            String id = String.valueOf(i);
            int[] quads = calcQuads(id.getBytes("UTF-8"));
            symbols.addName(id, quads, quads.length);
        }
        System.out.println("Size: " + symbols.size() + " (expected: " + COUNT + ")");
        System.out.println("BucketCount: " + symbols.bucketCount() + " (expected: 16384)");
        System.out.println("PrimaryCount: " + symbols.primaryCount() + " (expected: 5402)");
        System.out.println("SecondaryCount: " + symbols.secondaryCount() + " (expected: 2744)");
        System.out.println("TertiaryCount: " + symbols.tertiaryCount() + " (expected: 1834)");
        System.out.println("SpilloverCount: " + symbols.spilloverCount() + " (expected: 20)");
        System.out.println("Test completed successfully!");
    }

    private static int[] calcQuads(byte[] wordBytes) {
        int blen = wordBytes.length;
        int[] result = new int[(blen + 3) / 4];
        for (int i = 0; i < blen; ++i) {
            int x = wordBytes[i] & 0xFF;
            if (++i < blen) {
                x = (x << 8) | (wordBytes[i] & 0xFF);
                if (++i < blen) {
                    x = (x << 8) | (wordBytes[i] & 0xFF);
                    if (++i < blen) {
                        x = (x << 8) | (wordBytes[i] & 0xFF);
                    }
                }
            }
            result[i >> 2] = x;
        }
        return result;
    }
}
