        ObjectMapper MAPPER = new ObjectMapper();
        try {
            Map<ABC, Integer> map = MAPPER.readValue("{\"value\":\"foo\"}",
                new TypeReference<Map<ABC, Integer>>() { });
            System.out.println("Should not get here!");
        } catch (MismatchedInputException e) {
            String msg = e.getMessage();
            System.out.println("Exception message:");
            System.out.println(msg);
            System.out.println("\nNumber of ' at [' occurrences:");
            String[] str = msg.split(" at \\[");
            System.out.println(str.length - 1);
            if (str.length != 2) {
                System.out.println("TEST FAILED: Should only get one 'at [' marker, got "+(str.length-1));
                System.out.println("Parts:");
                for (int i = 0; i < str.length; i++) {
                    System.out.println(i + ": [" + str[i] + "]");
                }
            } else {
                System.out.println("TEST PASSED!");
            }
        }
    }
