import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.StringWriter;

public class test_context {
    public static void main(String[] args) throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        TokenBuffer buf = new TokenBuffer(null, false);
        StringWriter w = new StringWriter();
        JsonGenerator gen = mapper.getFactory().createGenerator(w);

        // Simple test: write field name then check context
        buf.writeStartObject();
        gen.writeStartObject();

        System.out.println("After writeStartObject:");
        System.out.println("  TokenBuffer context: " + buf.getOutputContext());
        System.out.println("  JsonGenerator context: " + gen.getOutputContext());

        buf.writeFieldName("a");
        gen.writeFieldName("a");

        System.out.println("\nAfter writeFieldName('a'):");
        System.out.println("  TokenBuffer context: " + buf.getOutputContext());
        System.out.println("  JsonGenerator context: " + gen.getOutputContext());
        System.out.println("  TokenBuffer current name: " + buf.getOutputContext().getCurrentName());
        System.out.println("  JsonGenerator current name: " + gen.getOutputContext().getCurrentName());

        buf.writeNumber(1);
        gen.writeNumber(1);

        System.out.println("\nAfter writeNumber(1):");
        System.out.println("  TokenBuffer context: " + buf.getOutputContext());
        System.out.println("  JsonGenerator context: " + gen.getOutputContext());
        System.out.println("  TokenBuffer current name: " + buf.getOutputContext().getCurrentName());
        System.out.println("  JsonGenerator current name: " + gen.getOutputContext().getCurrentName());

        buf.close();
        gen.close();
    }
}
