import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.annotation.*;
import java.util.*;

public class test_visibility {
    static class TCls {
        @JsonProperty("groupname")
        private String groupname;

        public void setName(String str) {
            this.groupname = str;
        }
        public String getName() {
            return groupname;
        }
    }

    public static void main(String[] args) throws Exception {
        ObjectMapper om = new ObjectMapper();
        om.configure(MapperFeature.AUTO_DETECT_FIELDS, false);
        om.configure(MapperFeature.AUTO_DETECT_GETTERS, false);
        om.configure(MapperFeature.AUTO_DETECT_SETTERS, false);
        om.configure(MapperFeature.AUTO_DETECT_IS_GETTERS, false);
        om.configure(MapperFeature.USE_GETTERS_AS_SETTERS, false);
        om.configure(MapperFeature.CAN_OVERRIDE_ACCESS_MODIFIERS, true);
        om.configure(MapperFeature.INFER_PROPERTY_MUTATORS, false);
        om.configure(MapperFeature.USE_ANNOTATIONS, true);

        JavaType javaType = om.getTypeFactory().constructType(TCls.class);

        // Check the visibility checker
        VisibilityChecker<?> vc = om.getSerializationConfig().getDefaultVisibilityChecker();
        System.out.println("Getter visibility: " + vc.getGetterVisibility());
        System.out.println("Setter visibility: " + vc.getSetterVisibility());

        BeanDescription desc = om.getSerializationConfig().introspect(javaType);
        List<BeanPropertyDefinition> props = desc.findProperties();

        System.out.println("Found " + props.size() + " properties:");
        for (BeanPropertyDefinition prop : props) {
            System.out.println("  - name=" + prop.getName() + ", internalName=" + prop.getInternalName());
        }
    }
}
