import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.TimeZone;

public class test_tz {
    public static void main(String[] args) throws Exception {
        String dateStr = "1970-01-01T00:00:00.000Z";

        // Test with UTC
        SimpleDateFormat sdf1 = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
        sdf1.setTimeZone(TimeZone.getTimeZone("UTC"));
        Date d1 = sdf1.parse(dateStr);
        System.out.println("UTC: " + d1.getTime());

        // Test with GMT-2
        SimpleDateFormat sdf2 = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
        sdf2.setTimeZone(TimeZone.getTimeZone("GMT-2"));
        Date d2 = sdf2.parse(dateStr);
        System.out.println("GMT-2: " + d2.getTime());

        System.out.println("Are they equal? " + (d1.getTime() == d2.getTime()));
    }
}
