import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class TestRegex {
    public static void main(String[] args) {
        Pattern unescapePattern = Pattern.compile("&(#(x|X)?([0-9a-fA-F]+)|[a-zA-Z]+\\d*);?");

        String[] tests = {
            "&num_rooms",
            "&int=VA",
            "&children",
            "&amp",
            "&amp;",
            "&reg",
            "&angst",
            "&angst;"
        };

        for (String test : tests) {
            Matcher m = unescapePattern.matcher(test);
            if (m.find()) {
                System.out.println("Test: " + test);
                System.out.println("  Group 0 (full match): '" + m.group(0) + "'");
                System.out.println("  Group 1 (name/num): '" + m.group(1) + "'");
                System.out.println("  Ends with ';': " + m.group(0).endsWith(";"));
                System.out.println();
            }
        }
    }
}
