            count++;
            System.out.println("Match #" + count + ": '" + m.group(0) + "' at position " + m.start() + "-" + m.end());
            System.out.println("  Group 1: '" + m.group(1) + "'");
            System.out.println("  Has semicolon: " + m.group(0).endsWith(";"));
        }
        System.out.println("Total matches: " + count);
    }
}
