import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

public class TestComprehensive {
    public static void main(String[] args) {
        // Test that extended entities without semicolon are NOT decoded
        testParse("&num_rooms", "&amp;num_rooms", "Extended entity 'num' without semicolon should not decode");
        testParse("&int=VA", "&amp;int=VA", "Extended entity 'int' without semicolon should not decode");
        testParse("&children", "&amp;children", "No entity match, should not decode");

        // Test that extended entities WITH semicolon ARE decoded
        testParse("&clubs;", "♣", "Extended entity 'clubs' with semicolon should decode");
        testParse("&clubsuit;", "♣", "Extended entity 'clubsuit' with semicolon should decode");

        // Test that invalid entities with semicolon are NOT decoded
        testParse("&clubsuite;", "&amp;clubsuite;", "Invalid entity 'clubsuite' should not decode");

        // Test that base entities without semicolon ARE decoded
        testParse("&amp", "&amp;", "Base entity 'amp' without semicolon should decode");
        testParse("&lt", "&lt;", "Base entity 'lt' without semicolon should decode");
        testParse("&reg", "®", "Base entity 'reg' without semicolon should decode");
    }

    static void testParse(String input, String expected, String description) {
        Document doc = Jsoup.parse(input);
        String output = doc.body().html();
        boolean pass = expected.equals(output);
        System.out.println((pass ? "✓ PASS" : "✗ FAIL") + ": " + description);
        if (!pass) {
            System.out.println("  Input:    " + input);
            System.out.println("  Expected: " + expected);
            System.out.println("  Got:      " + output);
        }
    }
}
