import org.jsoup.Jsoup;
import org.jsoup.safety.Whitelist;

public class test_deep_nesting {
    public static void main(String[] args) {
        // Create a deeply nested HTML structure (similar to 24,205 wbr tags mentioned in the bug)
        StringBuilder html = new StringBuilder();
        int depth = 10000; // Create 10,000 nested div elements

        for (int i = 0; i < depth; i++) {
            html.append("<div>");
        }
        html.append("Content");
        for (int i = 0; i < depth; i++) {
            html.append("</div>");
        }

        System.out.println("Testing with " + depth + " nested elements...");

        try {
            String clean = Jsoup.clean(html.toString(), Whitelist.relaxed());
            System.out.println("SUCCESS: Cleaned HTML without StackOverflowError!");
            System.out.println("Output length: " + clean.length() + " characters");

            // Test with sequential elements (like the wbr tags)
            StringBuilder html2 = new StringBuilder("<div>");
            for (int i = 0; i < 25000; i++) {
                html2.append("<wbr>");
            }
            html2.append("</div>");

            System.out.println("\nTesting with 25,000 sequential wbr elements...");
            String clean2 = Jsoup.clean(html2.toString(), Whitelist.relaxed());
            System.out.println("SUCCESS: Cleaned HTML with many wbr tags without StackOverflowError!");
            System.out.println("Output length: " + clean2.length() + " characters");

        } catch (StackOverflowError e) {
            System.err.println("FAILED: StackOverflowError occurred!");
            e.printStackTrace();
            System.exit(1);
        } catch (Exception e) {
            System.err.println("FAILED: Exception occurred: " + e.getMessage());
            e.printStackTrace();
            System.exit(1);
        }
    }
}
