import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Parser;
import org.jsoup.safety.Whitelist;

public class test_issue {
    public static void main(String[] args) {
        String htmlFragment = "<html></html>";
        System.out.println("Testing with: " + htmlFragment);

        // What parseBodyFragment does
        Document parsed = Parser.parseBodyFragment(htmlFragment, "");
        System.out.println("After parseBodyFragment:");
        System.out.println("  Full HTML: " + parsed.html());
        System.out.println("  Body HTML: " + parsed.body().html());

        // The problem: parseBodyFragment wraps the input in html/head/body tags
        // So when we check if <html></html> is valid, parseBodyFragment returns
        // a document with <html><head></head><body><html></html></body></html>
        // But then it only checks the body part, which is <html></html> inside the body

        boolean isValid = Jsoup.isValid(htmlFragment, Whitelist.none());
        System.out.println("isValid result: " + isValid);
        System.out.println("Expected: false (because <html> is not in whitelist)");
    }
}
