public class test_surrogates {
    public static void main(String[] args) {
        String CharU20000 = "\uD840\uDC00";
        String CharU20001 = "\uD840\uDC01";
        String CharUSuppCharHigh = "\uDC00";
        String CharUSuppCharLow = "\uD840";

        System.out.println("CharU20000 = " + toHex(CharU20000));
        System.out.println("CharU20001 = " + toHex(CharU20001));
        System.out.println("CharUSuppCharHigh = " + toHex(CharUSuppCharHigh));
        System.out.println("CharUSuppCharLow = " + toHex(CharUSuppCharLow));

        System.out.println("\nCharU20001.indexOf(CharUSuppCharLow) = " + CharU20001.indexOf(CharUSuppCharLow));
        System.out.println("CharUSuppCharLow isHighSurrogate = " + Character.isHighSurrogate(CharUSuppCharLow.charAt(0)));
        System.out.println("CharUSuppCharHigh isLowSurrogate = " + Character.isLowSurrogate(CharUSuppCharHigh.charAt(0)));
    }

    static String toHex(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            if (i > 0) sb.append(" ");
            sb.append(String.format("U+%04X", (int)s.charAt(i)));
        }
        return sb.toString();
    }
}
EOF
