cat > /tmp/test_iterations.java << 'EOF'
import org.apache.commons.math3.optim.nonlinear.vector.jacobian.LevenbergMarquardtOptimizer;
import org.apache.commons.math3.optim.*;
import org.apache.commons.math3.optim.nonlinear.vector.*;
import org.apache.commons.math3.analysis.MultivariateVectorFunction;
import org.apache.commons.math3.analysis.MultivariateMatrixFunction;
import org.apache.commons.math3.util.FastMath;

public class TestIterations {
    public static void main(String[] args) {
        LevenbergMarquardtOptimizer optim = new LevenbergMarquardtOptimizer();

        optim.optimize(new MaxEval(100), 
            new Target(new double[] { 1 }),
            new Weight(new double[] { 1 }),
            new InitialGuess(new double[] { 3 }),
            new ModelFunction(new MultivariateVectorFunction() {
                @Override
                public double[] value(double[] point) {
                    return new double[] { FastMath.pow(point[0], 4) };
                }
            }),
            new ModelFunctionJacobian(new MultivariateMatrixFunction() {
                @Override
                public double[][] value(double[] point) {
                    return new double[][] { { 0.25 * FastMath.pow(point[0], 3) } };
                }
            }));

        System.out.println("Evaluations: " + optim.getEvaluations());
        System.out.println("Iterations: " + optim.getIterations());
        System.out.println("Test " + (optim.getIterations() > 0 ? "PASSED" : "FAILED"));
    }
}
EOF
